from src.memoize import memoize

def test_basic_cache():
    calls = []
    @memoize
    def add(a, b):
        calls.append((a, b))
        return a + b
    assert add(1, 2) == 3
    assert add(1, 2) == 3  # cached
    assert len(calls) == 1

def test_different_args_not_cached():
    calls = []
    @memoize
    def sq(n):
        calls.append(n)
        return n * n
    sq(3)
    sq(4)
    sq(3)  # cached
    assert len(calls) == 2
    assert sq(3) == 9
    assert sq(4) == 16

def test_kwargs_cached():
    calls = []
    @memoize
    def greet(name, greeting='hello'):
        calls.append(name)
        return f'{greeting} {name}'
    greet('alice', greeting='hi')
    greet('alice', greeting='hi')  # cached
    assert len(calls) == 1

def test_preserves_name():
    @memoize
    def my_func():
        return 42
    assert my_func.__name__ == 'my_func'

def test_none_return_cached():
    calls = []
    @memoize
    def nothing(x):
        calls.append(x)
        return None
    nothing(5)
    nothing(5)
    assert len(calls) == 1
